// Offline-baked anatomical tactical-glove meshes. No network requests or runtime SDF.
// All groups attach to existing weapon wrist transforms; vertices are indexed and shared.
import * as THREE from 'three';
const SUPPORT={
  position:``,
  uv:``,
  faces:``,
  colors:``,
  verts:4736, tris:9468,
};
const TRIGGER={
  position:``,
  uv:``,
  faces:``,
  colors:``,
  verts:4248, tris:8496,
};
const INDEX={
  position:``,
  uv:``,
  faces:``,
  colors:``,
  verts:930, tris:1856,
};
const PISTOLSUPPORT={
  position:``,
  uv:``,
  faces:``,
  colors:``,
  verts:3432, tris:6864,
};
const PISTOLTRIGGER={
  position:``,
  uv:``,
  faces:``,
  colors:``,
  verts:4576, tris:9148,
};
const PISTOLINDEX={
  position:``,
  uv:``,
  faces:``,
  colors:``,
  verts:858, tris:1712,
};

function unpack(base64, TypedArray) {
  const bytes = Uint8Array.from(atob(base64),c => c.charCodeAt(0));
  return new TypedArray(bytes.buffer);
}
export function createBakedGlove(kind, material) {
  const meshes={support:SUPPORT,trigger:TRIGGER,index:INDEX,pistolSupport:PISTOLSUPPORT,pistolTrigger:PISTOLTRIGGER,pistolIndex:PISTOLINDEX};
  const src=meshes[kind];
  if(!src)throw new Error(`Unknown glove mesh: ${kind}`);
  const encoded=unpack(src.position,Int16Array);
  const uvEncoded=unpack(src.uv,Int16Array);
  const faces=unpack(src.faces,Uint16Array);
  const colors=unpack(src.colors,Uint8Array);
  const position=new Float32Array(encoded.length), uv=new Float32Array(uvEncoded.length);
  for(let i=0;i<position.length;i++)position[i]=encoded[i]/100000;
  for(let i=0;i<uv.length;i++)uv[i]=uvEncoded[i]/2000;
  const geometry=new THREE.BufferGeometry();
  geometry.setAttribute('position',new THREE.Float32BufferAttribute(position,3));
  geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
  geometry.setAttribute('color',new THREE.BufferAttribute(colors,3,true));
  geometry.setIndex(new THREE.BufferAttribute(faces,1));
  geometry.computeVertexNormals();
  const mesh=new THREE.Mesh(geometry,material);
  mesh.name=`fps-baked-${kind}-glove`;
  mesh.castShadow=false;mesh.receiveShadow=false;
  return mesh;
}
